add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_selected_variation_details' );

function perfectpixel_selected_variation_details() {
	global $product;
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	$labels = array(
		'sku'             => '{{variation_sku_label}}',
		'weight_html'     => '{{variation_weight_label}}',
		'dimensions_html' => '{{variation_dimensions_label}}',
	);
	?>
	<div class="perfectpixel-variation-details" hidden style="margin-bottom:1.5em"></div>
	<script>
	jQuery( function ( $ ) {
		var labels = <?php echo wp_json_encode( $labels ); ?>;
		var box    = $( '.perfectpixel-variation-details' );
		var empty  = [ '', 'N/A', '<?php echo esc_js( __( 'N/A', 'woocommerce' ) ); ?>' ];
		$( 'form.variations_form' )
			.on( 'found_variation', function ( e, v ) {
				box.empty();
				$.each( labels, function ( key, label ) {
					if ( v[ key ] && -1 === empty.indexOf( $( '<div>' ).html( v[ key ] ).text().trim() ) ) {
						box.append( $( '<div>' ).append( $( '<strong>' ).text( label + ' ' ), $( '<span>' ).text( $( '<div>' ).html( v[ key ] ).text() ) ) );
					}
				} );
				box.prop( 'hidden', ! box.children().length );
			} )
			.on( 'reset_data hide_variation', function () {
				box.empty().prop( 'hidden', true );
			} );
	} );
	</script>
	<?php
}
